using System.Text.Json.Serialization;

namespace Mint.App.Services.System.News.Tavily;

/// <summary>
/// Tavily API search response
/// </summary>
public sealed record TavilySearchResponse
{
    /// <summary>
    /// Answer generated by Tavily
    /// </summary>
    [JsonPropertyName("answer")]
    public string? Answer { get; init; }

    /// <summary>
    /// Search results
    /// </summary>
    [JsonPropertyName("results")]
    public required ICollection<TavilySearchResult> Results { get; init; }
}
